<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {ChevronRight,ArrowLeft,ChartColumn,ChartPie} from '@lucide/vue'
import {categoryPath,type Category,type Transaction} from './ledger'
import {categoryDistribution} from './ledgerStatistics'
import {money} from './ledgerViewModels'
import CategoryIcon from './CategoryIcon.vue'
import CategoryPicker from './CategoryPicker.vue'
const props=withDefaults(defineProps<{transactions:Transaction[];categories:Category[];bookId?:string;appearanceMode?:'system'|'light'|'dark';title?:string}>(),{appearanceMode:'system',title:'钱花在哪里'})
const parentId=ref<string|null>(null),mode=ref<'pie'|'bar'>('pie'),metric=ref<'ratio'|'amount'>('ratio'),selected=ref<string|null>(null)
const path=computed(()=>categoryPath(props.categories,parentId.value))
const distribution=computed(()=>categoryDistribution(props.transactions,props.categories,parentId.value,props.bookId))
const active=computed(()=>distribution.value.items.find(item=>item.id===selected.value))
const value=(item:{amount:number;percent:number})=>metric.value==='ratio'?`${item.percent.toFixed(1)}%`:money(item.amount)
watch(parentId,()=>selected.value=null)
watch(()=>props.bookId,()=>{parentId.value=null;selected.value=null})
watch(()=>props.categories,()=>{if(parentId.value&&!props.categories.some(category=>category.id===parentId.value))parentId.value=null})
function back(){parentId.value=path.value.at(-2)?.id||null}
</script>
<template>
  <article class="home-panel category-statistics" aria-label="分类支出统计">
    <header class="cs-heading"><div><h3>{{ title }}</h3><p>{{ parentId?'查看当前分类的下一级支出':'按一级分类汇总本人支出' }}</p></div><CategoryPicker v-model="parentId" :categories="categories" title="统计分类" placeholder="全部分类" flow-type="expense" :allow-unassigned="true" :appearance-mode="appearanceMode"><template #trigger="{open}"><button class="cs-category-filter" type="button" @click="open"><span>{{ path.at(-1)?.name||'全部分类' }}</span><ChevronRight :size="14"/></button></template></CategoryPicker></header>
    <nav v-if="parentId" class="cs-breadcrumb" aria-label="统计分类层级"><button type="button" aria-label="返回上一级分类统计" @click="back"><ArrowLeft :size="14"/></button><button type="button" @click="parentId=null">全部</button><template v-for="category in path" :key="category.id"><ChevronRight :size="12"/><button type="button" :aria-current="category.id===parentId?'location':undefined" @click="parentId=category.id">{{ category.name }}</button></template></nav>
    <div class="cs-controls"><div class="cs-segments" role="group" aria-label="分类图表样式"><button type="button" :aria-pressed="mode==='pie'" @click="mode='pie'"><ChartPie :size="14"/>环图</button><button type="button" :aria-pressed="mode==='bar'" @click="mode='bar'"><ChartColumn :size="14"/>柱图</button></div><div class="cs-segments" role="group" aria-label="分类图表数值"><button type="button" :aria-pressed="metric==='ratio'" @click="metric='ratio'">占比</button><button type="button" :aria-pressed="metric==='amount'" @click="metric='amount'">金额</button></div></div>
    <template v-if="distribution.items.length">
      <div v-if="mode==='pie'" class="cs-donut-wrap"><div class="cs-donut"><svg viewBox="0 0 220 220" role="group" aria-label="点击扇区查看分类数值"><circle class="cs-ring-track" cx="110" cy="110" r="84" fill="none" stroke-width="22"/><circle v-for="item in distribution.items" :key="item.id" cx="110" cy="110" r="84" pathLength="100" fill="none" :stroke="item.color" :stroke-width="active?.id===item.id?27:22" :stroke-dasharray="`${Math.max(.05,item.percent-Math.min(.8,item.percent/4))} 100`" :stroke-dashoffset="-item.start" transform="rotate(-90 110 110)" class="cs-sector" :class="{muted:active&&active.id!==item.id}" tabindex="0" role="button" :aria-label="`${item.name}，${money(item.amount)}，${item.percent.toFixed(1)}%`" :aria-pressed="selected===item.id" @click="selected=selected===item.id?null:item.id" @keydown.enter.prevent="selected=selected===item.id?null:item.id" @keydown.space.prevent="selected=selected===item.id?null:item.id"><title>{{ item.name }} {{ money(item.amount) }} · {{ item.percent.toFixed(1) }}%</title></circle></svg><div class="cs-donut-center" aria-live="polite"><small>{{ active?.name||path.at(-1)?.name||'分类总支出' }}</small><strong>{{ active?value(active):money(distribution.total) }}</strong><span>{{ active?`${active.count} 笔流水`:`${distribution.items.length} 个分类` }}</span></div></div></div>
      <div class="cs-list" :class="{'is-bar':mode==='bar'}"><button v-for="item in distribution.items" :key="item.id" type="button" class="cs-row" :class="{selected:selected===item.id}" :aria-label="`${item.name}，${value(item)}${item.canDrill?'，查看下级分类':''}`" @click="item.canDrill?parentId=item.categoryId:selected=selected===item.id?null:item.id"><span class="cs-row-icon" :style="{color:item.color}"><CategoryIcon :name="item.icon" :category-name="item.name" :size="19"/></span><span class="cs-row-name"><b>{{ item.name }}</b><small>{{ item.count }} 笔{{ item.canDrill?' · 查看下级':'' }}</small></span><span class="cs-row-value"><b>{{ value(item) }}</b><small>{{ metric==='ratio'?money(item.amount):`${item.percent.toFixed(1)}%` }}</small></span><ChevronRight v-if="item.canDrill" class="cs-row-next" :size="14"/><span v-if="mode==='bar'" class="cs-bar"><i :style="{width:`${metric==='ratio'?item.percent:item.amount/distribution.items[0]!.amount*100}%`,background:item.color}"></i></span></button></div>
      <footer class="cs-footnote">{{ parentId?'当前分类':'本区间' }}合计 <b>{{ money(distribution.total) }}</b><span>有下级的分类可继续点开</span></footer>
    </template>
    <div v-else class="cs-empty"><ChartPie :size="32"/><b>当前范围暂无支出</b><p>调整分类或统计周期后再看看</p><button v-if="parentId" type="button" @click="parentId=null">查看全部分类</button></div>
  </article>
</template>
<style scoped>
.category-statistics{min-width:0;container-type:inline-size}.cs-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:17px}.cs-heading>div:first-child{min-width:0}.cs-heading h3{margin:0 0 7px;font-size:15px}.cs-heading p{margin:0;color:var(--app-muted);font-size:11px;line-height:1.7}.cs-heading :deep(.category-picker){max-width:45%;min-width:0}.cs-category-filter{display:flex;align-items:center;gap:5px;max-width:100%;min-height:34px;padding:8px 10px;border:1px solid var(--app-line);border-radius:10px;background:var(--app-raised);color:var(--app-accent);font:inherit;font-size:11px;cursor:pointer}.cs-category-filter>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cs-category-filter>svg{flex:none}.cs-controls{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:9px;margin-bottom:14px}.cs-segments{display:flex;gap:3px;padding:3px;background:var(--app-raised);border:1px solid var(--app-line);border-radius:10px}.cs-segments>button{display:flex;align-items:center;justify-content:center;gap:5px;min-height:31px;padding:6px 11px;border:0;border-radius:7px;background:transparent;color:var(--app-muted);font:inherit;font-size:11px;cursor:pointer}.cs-segments>button[aria-pressed=true]{background:var(--app-soft);color:var(--app-accent);font-weight:600}.cs-breadcrumb{display:flex;align-items:center;gap:5px;overflow:auto;margin:-2px 0 14px;padding-bottom:3px;color:var(--app-muted)}.cs-breadcrumb>button{flex:none;border:0;background:transparent;color:inherit;padding:5px 2px;font:inherit;font-size:11px;cursor:pointer}.cs-breadcrumb>svg{flex:none}.cs-breadcrumb [aria-current]{color:var(--app-accent);font-weight:600}.cs-donut-wrap{display:flex;justify-content:center;padding:0 0 14px}.cs-donut{position:relative;width:220px;max-width:100%;aspect-ratio:1}.cs-donut>svg{display:block;width:100%;height:100%;overflow:visible}.cs-ring-track{stroke:var(--app-raised)}.cs-sector{cursor:pointer;transition:opacity .18s,stroke-width .18s}.cs-sector.muted{opacity:.35}.cs-sector:focus-visible{outline:0;stroke-width:30}.cs-donut-center{position:absolute;inset:28%;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px;pointer-events:none;text-align:center}.cs-donut-center small{max-width:140px;color:var(--app-muted);font-size:11px;overflow-wrap:anywhere}.cs-donut-center strong{color:var(--app-ink);font-size:17px;letter-spacing:-.5px;font-variant-numeric:tabular-nums;white-space:nowrap}.cs-donut-center span{color:var(--app-muted);font-size:10px}.cs-list{display:grid;gap:3px;min-width:0}.cs-row{display:grid;grid-template-columns:31px minmax(0,1fr) auto 14px;align-items:center;gap:8px;min-width:0;width:100%;padding:10px 2px;border:0;border-bottom:1px solid var(--app-line);background:transparent;color:var(--app-ink);font:inherit;text-align:left;cursor:pointer}.cs-row:last-child{border-bottom:0}.cs-row.selected{background:var(--app-soft);border-radius:10px}.cs-row-icon{display:grid;place-items:center;width:31px;height:34px;flex:none}.cs-row-name,.cs-row-value{display:flex;flex-direction:column;gap:5px;min-width:0}.cs-row-name>b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;font-weight:500}.cs-row-name>small,.cs-row-value>small{font-size:10px;color:var(--app-muted)}.cs-row-value{grid-column:3;text-align:right;font-variant-numeric:tabular-nums}.cs-row-value>b{font-size:13px;font-weight:650;white-space:nowrap}.cs-row-next{color:var(--app-muted);grid-column:4}.cs-bar{grid-column:2/-1;display:block;height:8px;margin-top:1px;overflow:hidden;border-radius:8px;background:var(--app-raised)}.cs-bar>i{display:block;height:100%;min-width:2px;border-radius:8px}.is-bar{gap:8px}.is-bar .cs-row{padding-bottom:14px}.cs-footnote{display:flex;flex-wrap:wrap;gap:6px;margin-top:15px;padding-top:13px;border-top:1px solid var(--app-line);color:var(--app-muted);font-size:10px;line-height:1.8}.cs-footnote>b{color:var(--app-ink);font-weight:500}.cs-footnote>span{margin-left:auto}.cs-empty{display:flex;align-items:center;flex-direction:column;gap:12px;padding:35px 0;color:var(--app-muted);text-align:center}.cs-empty>b{font-size:13px;color:var(--app-ink)}.cs-empty>p{margin:0;font-size:11px}.cs-empty>button{border:0;background:transparent;color:var(--app-accent);font:inherit;font-size:12px;cursor:pointer}.category-statistics button:focus-visible{outline:2px solid var(--app-accent);outline-offset:2px}@media(max-width:400px){.cs-heading{gap:8px}.cs-heading h3{font-size:14px}.cs-heading p{font-size:10px}.cs-segments>button{padding:6px 9px}.cs-row{gap:6px;grid-template-columns:27px minmax(0,1fr) auto 12px}.cs-footnote>span{width:100%;margin:0}}
</style>
